import json
import csv
import os
import sys
from datetime import datetime, timedelta
from collections import defaultdict

def read_csv_file(packet_dir, filename):
    """Read CSV file and return list of dicts."""
    filepath = os.path.join(packet_dir, filename)
    with open(filepath, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        return list(reader)

def excel_serial_to_date(serial):
    """Convert Excel serial number to YYYY-MM-DD string."""
    if serial == '':
        return None
    try:
        # Excel's epoch is 1899-12-30 (or 1900-01-00)
        base = datetime(1899, 12, 30)
        days = int(float(serial))
        date = base + timedelta(days=days)
        return date.strftime('%Y-%m-%d')
    except:
        return None

def process_packet(packet_dir, manifest_file):
    with open(manifest_file, 'r') as f:
        manifest = json.load(f)

    pairs = manifest['pairs']
    facts = manifest['facts']

    # Read all necessary data files
    lca_data = {}
    lca_file = 'lca_disclosure.csv'
    lca_path = os.path.join(packet_dir, lca_file)
    if os.path.exists(lca_path):
        with open(lca_path, 'r', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            for row in reader:
                case_num = row['CASE_NUMBER']
                lca_data[case_num] = row

    result = {}

    for pair in pairs:
        rule_id, entity = pair.split('::')
        result[pair] = {}

        for fact_name in facts[rule_id]:
            if rule_id == 'lca.wage_105':
                if fact_name == 'offered wage':
                    if entity in lca_data:
                        value = lca_data[entity].get('WAGE_RATE_OF_PAY_FROM', '').strip()
                        if value:
                            # Convert to decimal string
                            try:
                                # Remove commas if present
                                value = value.replace(',', '')
                                # Check if it's a float
                                float_val = float(value)
                                # Format without unnecessary decimal places
                                if float_val.is_integer():
                                    value = str(int(float_val))
                                else:
                                    value = str(float_val)
                                result[pair][fact_name] = [value, 'lca_disclosure']
                            except:
                                result[pair][fact_name] = "ABSENT"
                        else:
                            result[pair][fact_name] = "ABSENT"
                    else:
                        result[pair][fact_name] = "ABSENT"

                elif fact_name == 'prevailing wage':
                    if entity in lca_data:
                        value = lca_data[entity].get('PREVAILING_WAGE', '').strip()
                        if value:
                            try:
                                value = value.replace(',', '')
                                float_val = float(value)
                                if float_val.is_integer():
                                    value = str(int(float_val))
                                else:
                                    value = str(float_val)
                                result[pair][fact_name] = [value, 'lca_disclosure']
                            except:
                                result[pair][fact_name] = "ABSENT"
                        else:
                            result[pair][fact_name] = "ABSENT"
                    else:
                        result[pair][fact_name] = "ABSENT"

            elif rule_id == 'lca.three_years':
                if fact_name == 'begin date':
                    if entity in lca_data:
                        value = lca_data[entity].get('BEGIN_DATE', '').strip()
                        if value:
                            date_str = excel_serial_to_date(value)
                            if date_str:
                                result[pair][fact_name] = [date_str, 'lca_disclosure']
                            else:
                                result[pair][fact_name] = "ABSENT"
                        else:
                            result[pair][fact_name] = "ABSENT"
                    else:
                        result[pair][fact_name] = "ABSENT"

                elif fact_name == 'end date':
                    if entity in lca_data:
                        value = lca_data[entity].get('END_DATE', '').strip()
                        if value:
                            date_str = excel_serial_to_date(value)
                            if date_str:
                                result[pair][fact_name] = [date_str, 'lca_disclosure']
                            else:
                                result[pair][fact_name] = "ABSENT"
                        else:
                            result[pair][fact_name] = "ABSENT"
                    else:
                        result[pair][fact_name] = "ABSENT"

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_file = sys.argv[2]
    process_packet(packet_dir, manifest_file)
