import json
import csv
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path

def read_csv_file(packet_dir, filename):
    """Read CSV file and return list of dicts."""
    filepath = os.path.join(packet_dir, filename)
    with open(filepath, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        return list(reader)

def excel_date_to_iso(excel_date_str):
    """Convert Excel serial date to ISO format YYYY-MM-DD."""
    if not excel_date_str:
        return None
    try:
        # Excel date is days since 1899-12-30 (with 1900 leap year bug)
        days = int(float(excel_date_str))
        # Excel's epoch is 1899-12-30
        base = datetime(1899, 12, 30)
        date = base + timedelta(days=days)
        return date.strftime('%Y-%m-%d')
    except (ValueError, TypeError):
        return None

def extract_facts(packet_dir, manifest):
    """Extract facts based on manifest."""
    # Read the LCA disclosure file
    lca_data = read_csv_file(packet_dir, "lca_disclosure.csv")

    # Create mapping from CASE_NUMBER to row
    case_to_row = {row['CASE_NUMBER']: row for row in lca_data}

    # Initialize result structure
    result = {}

    # Process each pair
    for pair in manifest['pairs']:
        rule_id, entity = pair.split('::')
        fact_names = manifest['facts'][rule_id]

        # Initialize facts for this pair
        pair_facts = {}

        if rule_id == 'lca.wage_105':
            if entity in case_to_row:
                row = case_to_row[entity]

                # Extract offered wage
                offered_wage_str = row.get('WAGE_RATE_OF_PAY_FROM', '').strip()
                if offered_wage_str:
                    try:
                        offered_wage = float(offered_wage_str)
                        pair_facts['offered wage'] = [str(offered_wage), "lca_disclosure"]
                    except ValueError:
                        pair_facts['offered wage'] = "ABSENT"
                else:
                    pair_facts['offered wage'] = "ABSENT"

                # Extract prevailing wage
                prevailing_wage_str = row.get('PREVAILING_WAGE', '').strip()
                if prevailing_wage_str:
                    try:
                        prevailing_wage = float(prevailing_wage_str)
                        pair_facts['prevailing wage'] = [str(prevailing_wage), "lca_disclosure"]
                    except ValueError:
                        pair_facts['prevailing wage'] = "ABSENT"
                else:
                    pair_facts['prevailing wage'] = "ABSENT"
            else:
                pair_facts['offered wage'] = "ABSENT"
                pair_facts['prevailing wage'] = "ABSENT"

        elif rule_id == 'lca.three_years':
            if entity in case_to_row:
                row = case_to_row[entity]

                # Extract begin date
                begin_date_str = row.get('BEGIN_DATE', '').strip()
                if begin_date_str:
                    iso_date = excel_date_to_iso(begin_date_str)
                    if iso_date:
                        pair_facts['begin date'] = [iso_date, "lca_disclosure"]
                    else:
                        pair_facts['begin date'] = "ABSENT"
                else:
                    pair_facts['begin date'] = "ABSENT"

                # Extract end date
                end_date_str = row.get('END_DATE', '').strip()
                if end_date_str:
                    iso_date = excel_date_to_iso(end_date_str)
                    if iso_date:
                        pair_facts['end date'] = [iso_date, "lca_disclosure"]
                    else:
                        pair_facts['end date'] = "ABSENT"
                else:
                    pair_facts['end date'] = "ABSENT"
            else:
                pair_facts['begin date'] = "ABSENT"
                pair_facts['end date'] = "ABSENT"

        result[pair] = pair_facts

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Read manifest
    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    # Extract facts
    result = extract_facts(packet_dir, manifest)

    # Output result as JSON
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
